SELECT FROM proj_project_task task
JOIN proj_task_tree_path path ON path.tenant_id = task.tenant_id AND path.project_id = task.project_id AND path.descendant_task_id = task.id AND path.ancestor_task_id = #{query.targetTaskId} AND path.distance > 0 AND path.deleted = b'0'
JOIN proj_task_tree_path path ON path.tenant_id = task.tenant_id AND path.project_id = task.project_id AND path.ancestor_task_id = task.id AND path.descendant_task_id = #{query.targetTaskId} AND path.distance > 0 AND path.deleted = b'0'
WHERE task.tenant_id = #{query.tenantId} AND task.deleted = b'0' AND task.project_id IN
#{projectId}
AND TRUE
AND EXISTS ( SELECT 1 FROM proj_task_tree_path visible_path JOIN proj_project_task_assignment assignment ON assignment.tenant_id = visible_path.tenant_id AND assignment.project_task_id = visible_path.descendant_task_id AND assignment.current_marker = 1 AND assignment.effective_to IS NULL AND assignment.deleted = b'0' WHERE visible_path.tenant_id = task.tenant_id AND visible_path.project_id = task.project_id AND visible_path.ancestor_task_id = task.id AND visible_path.deleted = b'0' AND assignment.assignee_user_id = #{query.visibilityQuery.actorId} )
AND task.id IN
#{taskId}
AND task.parent_task_id = #{query.parentTaskId}
AND task.parent_task_id IS NULL
AND task.business_level_code = #{query.businessLevelCode}
AND
AND task.id = #{query.targetTaskId}
AND (task.task_code LIKE CONCAT('%', #{query.keyword}, '%') OR task.name LIKE CONCAT('%', #{query.keyword}, '%'))
AND
AND task.stage_code = #{query.stageCode}
AND (COALESCE(task.sort_order, 0) > #{query.cursorSortOrder} OR (COALESCE(task.sort_order, 0) = #{query.cursorSortOrder} AND task.id > #{query.cursorTaskId}))
ORDER BY COALESCE(task.sort_order, 0), task.id LIMIT #{query.pageSize}

SELECT DISTINCT FROM proj_task_tree_path path JOIN proj_project_task task ON task.tenant_id = path.tenant_id AND task.project_id = path.project_id AND task.id = path.ancestor_task_id AND task.deleted = b'0' WHERE path.tenant_id = #{query.tenantId} AND path.project_id = #{query.projectId} AND path.descendant_task_id IN
#{taskId}
AND path.distance > 0 AND path.deleted = b'0' AND ORDER BY task.tree_depth, COALESCE(task.sort_order, 0), task.id

