WHERE task.tenant_id = #{query.tenantId}
  AND task.id = #{query.taskId}
  AND task.deleted = b'0'

SELECT FROM proj_project_task task WHERE task.tenant_id = #{query.tenantId} AND task.project_id IN
#{projectId}
AND task.deleted = b'0' ORDER BY task.project_id, task.id

