UPDATE proj_project_task
SET parent_task_id = #{query.targetParentTaskId},
    root_task_id = #{query.newRootTaskId},
    tree_depth = #{query.newTreeDepth},
    version = version + 1,
    updater = #{query.updater},
    update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND id = #{query.taskId}
  AND version = #{query.expectedTaskVersion}
  AND deleted = b'0'

UPDATE proj_project
SET task_tree_version = task_tree_version + 1,
    updater = #{query.updater},
    update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.projectId}
  AND task_tree_version = #{query.expectedTaskTreeVersion}
  AND deleted = b'0'

mapper.insert:
INSERT INTO proj_task_tree_path
    (project_id, ancestor_task_id, descendant_task_id, distance,
     version, creator, updater, tenant_id)
SELECT #{query.projectId}, ancestor_task_id, #{query.taskId}, distance + 1,
       0, #{query.creator}, #{query.creator}, #{query.tenantId}
FROM proj_task_tree_path
WHERE #{query.parentTaskId} IS NOT NULL
  AND tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND descendant_task_id = #{query.parentTaskId}
  AND deleted = b'0'
UNION ALL
SELECT #{query.projectId}, #{query.taskId}, #{query.taskId}, 0,
       0, #{query.creator}, #{query.creator}, #{query.tenantId}

