UPDATE proj_project_task
SET version = version + 1,
    updater = #{query.updater},
    update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.taskId}
  AND version = #{query.expectedVersion}
  AND deleted = b'0'

UPDATE proj_project_task
SET status = #{query.nextStatus},
    version = version + 1,
    updater = #{query.updater},
    update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND id = #{query.projectTaskId}
  AND version = #{query.expectedVersion}
  AND status = #{query.expectedStatus}
  AND deleted = b'0'

UPDATE proj_project_task
SET status = #{query.nextStatus},

    actual_start_time = COALESCE(actual_start_time, #{query.occurredAt}),


    actual_end_time = #{query.occurredAt},


    progress = #{query.progress},

    version = version + 1,
    updater = #{query.updater},
    update_time = #{query.occurredAt}
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND id = #{query.projectTaskId}
  AND version = #{query.expectedVersion}
  AND status = #{query.expectedStatus}
  AND deleted = b'0'

UPDATE proj_project_task
SET progress = #{query.progress},
    version = version + 1,
    updater = #{query.updater},
    update_time = #{query.occurredAt}
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND id = #{query.projectTaskId}
  AND version = #{query.expectedVersion}
  AND status = 'IN_PROGRESS'
  AND deleted = b'0'

UPDATE proj_project
SET task_progress_version = task_progress_version + 1,
    updater = #{query.updater},
    update_time = #{query.occurredAt}
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.projectId}
  AND task_progress_version = #{query.expectedVersion}
  AND deleted = b'0'
